using System.Text.Json.Nodes;
namespace Koz.Application.AdminCustomers;
public sealed class AdminCustomerService(IAdminCustomerRepository r){
 public Task<JsonObject> ListAsync(AdminCustomerQuery q,CancellationToken ct)=>r.ListAsync(Normalize(q),ct); public Task<JsonObject> DetailAsync(string id,CancellationToken ct){Id(id);return r.DetailAsync(id,ct);} public Task<JsonObject> SubscriptionsAsync(AdminSubscriptionQuery q,CancellationToken ct)=>r.SubscriptionsAsync(q,ct); public Task<JsonObject> RenewAsync(string id,CancellationToken ct){Id(id);return r.RenewAsync(id,ct);} public Task<JsonObject> PauseAsync(string id,CancellationToken ct){Id(id);return r.PauseAsync(id,ct);} public Task<JsonObject> CancelAsync(string id,AdminCancelRequest? b,CancellationToken ct){Id(id);return r.CancelAsync(id,b?.Immediate==true,ct);}public Task<JsonObject> ConsentAsync(CancellationToken ct)=>r.ConsentLogsAsync(ct);public Task<JsonObject> ExportAsync(AdminCustomerQuery q,CancellationToken ct)=>r.ExportAsync(Normalize(q),ct);
 static AdminCustomerQuery Normalize(AdminCustomerQuery q){var p=Positive(q.Page,1);var l=Math.Min(Positive(q.Limit,20),100);return q with{Page=p.ToString(),Limit=l.ToString()};} static int Positive(string? s,int d)=>int.TryParse(s,out var n)&&n>0?n:d;static void Id(string id){if(!Guid.TryParse(id,out _))throw new AdminCustomerContractException(404,"Customer was not found","customer_not_found");}}
